// VcsServiceHandler is an implementation of the harness.vcs.v1.VcsService service.
type VcsServiceHandler interface {
	// --- Admin: provider connections ---
	ListConnections(context.Context, *connect.Request[v1.ListConnectionsRequest]) (*connect.Response[v1.ListConnectionsResponse], error)
	// Returns the GitHub App manifest and the URL to post it to (github.com or a GHES host, user or org).
	GetGitHubAppManifest(context.Context, *connect.Request[v1.GetGitHubAppManifestRequest]) (*connect.Response[v1.GetGitHubAppManifestResponse], error)
	// Exchanges the manifest flow `code` for the app credentials and stores the connection.
	CompleteGitHubAppManifest(context.Context, *connect.Request[v1.CompleteGitHubAppManifestRequest]) (*connect.Response[v1.CompleteGitHubAppManifestResponse], error)
	// Creates or updates a connection with explicit credentials (GitLab, or a manually created GitHub App).
	PutConnection(context.Context, *connect.Request[v1.PutConnectionRequest]) (*connect.Response[v1.PutConnectionResponse], error)
	DeleteConnection(context.Context, *connect.Request[v1.DeleteConnectionRequest]) (*connect.Response[v1.DeleteConnectionResponse], error)
	// --- Per-user authorization (act as the user: open PRs, comment, merge) ---
	StartUserAuth(context.Context, *connect.Request[v1.StartUserAuthRequest]) (*connect.Response[v1.StartUserAuthResponse], error)
	GetUserAuthStatus(context.Context, *connect.Request[v1.GetUserAuthStatusRequest]) (*connect.Response[v1.GetUserAuthStatusResponse], error)
	RevokeUserAuth(context.Context, *connect.Request[v1.RevokeUserAuthRequest]) (*connect.Response[v1.RevokeUserAuthResponse], error)
	// The connections any signed-in user can use, with where that user stands on each. No secrets, no health details.
	ListUserConnections(context.Context, *connect.Request[v1.ListUserConnectionsRequest]) (*connect.Response[v1.ListUserConnectionsResponse], error)
	// --- Repositories and pull/merge requests ---
	ListRepositories(context.Context, *connect.Request[v1.ListRepositoriesRequest]) (*connect.Response[v1.ListRepositoriesResponse], error)
	ListPullRequests(context.Context, *connect.Request[v1.ListPullRequestsRequest]) (*connect.Response[v1.ListPullRequestsResponse], error)
	GetPullRequest(context.Context, *connect.Request[v1.GetPullRequestRequest]) (*connect.Response[v1.GetPullRequestResponse], error)
	CreatePullRequest(context.Context, *connect.Request[v1.CreatePullRequestRequest]) (*connect.Response[v1.CreatePullRequestResponse], error)
	MergePullRequest(context.Context, *connect.Request[v1.MergePullRequestRequest]) (*connect.Response[v1.MergePullRequestResponse], error)
	SetAutoMerge(context.Context, *connect.Request[v1.SetAutoMergeRequest]) (*connect.Response[v1.SetAutoMergeResponse], error)
	ListReviewComments(context.Context, *connect.Request[v1.ListReviewCommentsRequest]) (*connect.Response[v1.ListReviewCommentsResponse], error)
	PostComment(context.Context, *connect.Request[v1.PostCommentRequest]) (*connect.Response[v1.PostCommentResponse], error)
	// --- CI ---
	ListChecks(context.Context, *connect.Request[v1.ListChecksRequest]) (*connect.Response[v1.ListChecksResponse], error)
	// Log of a failed check/job, tail-truncated, for auto-fix and the UI.
	GetCheckLog(context.Context, *connect.Request[v1.GetCheckLogRequest]) (*connect.Response[v1.GetCheckLogResponse], error)
	// --- Sessions ---
	// Links a session to a repo + branch (and the PR once it exists). The server derives the link from
	// synced session metadata (repo, branch) automatically; this is for explicit linking.
	LinkSession(context.Context, *connect.Request[v1.LinkSessionRequest]) (*connect.Response[v1.LinkSessionResponse], error)
	// Auto-fix: on CI failure or new review comments, the server delivers the failure (logs, comments) to
	// the linked session through the relay, or spawns one on a daemon host if none is live.
	SetAutoFix(context.Context, *connect.Request[v1.SetAutoFixRequest]) (*connect.Response[v1.SetAutoFixResponse], error)
	// Live events for the caller's repos/sessions: catch-up after `after_id`, then live; heartbeat 20 s.
	WatchEvents(context.Context, *connect.Request[v1.WatchEventsRequest], *connect.ServerStream[v1.WatchEventsResponse]) error
	// --- Device providers (gh, glab) ---
	// A client reports which device providers it has (CLI installed, logged in, hosts covered).
	ReportDeviceProviders(context.Context, *connect.Request[v1.ReportDeviceProvidersRequest]) (*connect.Response[v1.ReportDeviceProvidersResponse], error)
	// A client uploads PR and CI state it polled through gh/glab; the server stores it, links it to sessions
	// and emits the same VcsEvents (source = device) as webhooks would.
	ReportDeviceSnapshot(context.Context, *connect.Request[v1.ReportDeviceSnapshotRequest]) (*connect.Response[v1.ReportDeviceSnapshotResponse], error)
}

